class Solution {
public:
    long long countValidSubstrings(string s) {
        long long ans = 0;
        int p = -1;
        int n = (int)s.size();
        for (int r = 0; r < n; r++) {
            if (r >= 2 && s[r - 2] == 'a' && s[r - 1] == 'b' && s[r] == 'c') {
                p = r - 2;
            }
            ans += (long long)(r - p);
        }
        return ans;
    }
};
